#!/usr/bin/env python3
"""Writes crates/rdoxide/src/external/freesasa/classifier_data.rs from the autogenerated classifier_{protor,naccess,oons}.c
of freesasa 2.0.3.

    python3 tools/gen_freesasa_classifiers.py FREESASA_SRC_DIR > crates/rdoxide/src/external/freesasa/classifier_data.rs
"""
import re
import sys

src = sys.argv[1]
print("// @generated by tools/gen_freesasa_classifiers.py from freesasa 2.0.3 (MIT, see LICENSES/FreeSASA-MIT.txt)")
print("// (residue, [(atom, radius, class)]) with class 0 = apolar, 1 = polar, 2 = unknown\n")
print("pub type Residue = (&'static str, &'static [(&'static str, f64, u8)]);\n")
for key, const in (("protor", "PROTOR"), ("naccess", "NACCESS"), ("oons", "OONS")):
    text = open("%s/classifier_%s.c" % (src, key)).read()
    names = re.search(r"static const char \*%s_residue_name\[\] = \{(.*?)\};" % key, text).group(1)
    names = re.findall(r'"([^"]*)"', names)
    cname = re.search(r'freesasa_%s_classifier = \{\s*\d+,\s*\(char\*\*\) \w+,\s*"([^"]*)"' % key, text).group(1)
    print('pub const %s_NAME: &str = "%s";' % (const, cname))
    print("pub static %s: &[Residue] = &[" % const)
    for r in names:
        an = re.search(r"static const char \*%s_%s_atom_name\[\] = \{(.*?)\};" % (key, re.escape(r)), text, re.S)
        ar = re.search(r"static double %s_%s_atom_radius\[\] = \{(.*?)\};" % (key, re.escape(r)), text, re.S)
        ac = re.search(r"static int %s_%s_atom_class\[\] = \{(.*?)\};" % (key, re.escape(r)), text, re.S)
        if an is None:
            print('    ("%s", &[]),' % r)
            continue
        ns = re.findall(r'"([^"]*)"', an.group(1))
        rs = [x.strip() for x in ar.group(1).split(",") if x.strip()]
        cs = [{"FREESASA_ATOM_APOLAR": 0, "FREESASA_ATOM_POLAR": 1, "FREESASA_ATOM_UNKNOWN": 2}[x.strip()]
              for x in ac.group(1).split(",") if x.strip()]
        assert len(ns) == len(rs) == len(cs), (key, r)
        print('    ("%s", &[' % r)
        for n, rad, c in zip(ns, rs, cs):
            print('        ("%s", %s, %d),' % (n, rad, c))
        print("    ]),")
    print("];\n")
